function BookForedgeFanMaker.init() BookForedgeFanMaker.ironStock=14; BookForedgeFanMaker.bronzeStock=12; BookForedgeFanMaker.woodStock=14; BookForedgeFanMaker.leatherStock=8; BookForedgeFanMaker.silverStock=8; BookForedgeFanMaker.goldStock=6; BookForedgeFanMaker.jewelStock=4; BookForedgeFanMaker.pearlStock=4; BookForedgeFanMaker.productStock={}; BookForedgeFanMaker.buildings={}; BookForedgeFanMaker.maker=nil; BookForedgeFanMaker.activeMaking={}; BookForedgeFanMaker.totalProducts=0; BookForedgeFanMaker.dayTimer=0; print("[BookForedgeFanMaker] Royal Book Foredge Fan Maker System initialized (6 products, 4 buildings)") end
function BookForedgeFanMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookForedgeFanMaker.maker={name=n or ("Ventilator "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ventilator najet: %s (spretnost: %d)",BookForedgeFanMaker.maker.name,s),"success") end; return true end
function BookForedgeFanMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookForedgeFanMaker.build(id) local ok,e=BookForedgeFanMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookForedgeFanMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookForedgeFanMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookForedgeFanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookForedgeFanMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookForedgeFanMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookForedgeFanMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookForedgeFanMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookForedgeFanMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookForedgeFanMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookForedgeFanMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookForedgeFanMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookForedgeFanMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookForedgeFanMaker.buildings==0 then return false,"Potrebna ventilatorska delavnica" end; if not BookForedgeFanMaker.maker then return false,"Potreben ventilator" end; return true end
function BookForedgeFanMaker.make(pt,qty) qty=qty or 1; local ok,e=BookForedgeFanMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookForedgeFanMaker.ironStock=BookForedgeFanMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookForedgeFanMaker.bronzeStock=BookForedgeFanMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookForedgeFanMaker.woodStock=BookForedgeFanMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookForedgeFanMaker.leatherStock=BookForedgeFanMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookForedgeFanMaker.silverStock=BookForedgeFanMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookForedgeFanMaker.goldStock=BookForedgeFanMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookForedgeFanMaker.jewelStock=BookForedgeFanMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookForedgeFanMaker.pearlStock=BookForedgeFanMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookForedgeFanMaker.maker then t=math.max(1,t-math.floor(BookForedgeFanMaker.maker.skill/13)) end; table.insert(BookForedgeFanMaker.activeMaking,{id="bookforedgefan_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookForedgeFanMaker.completeMaking(m) local q=1.0+(BookForedgeFanMaker.getQualityBonus()/100); if BookForedgeFanMaker.maker then q=q+(BookForedgeFanMaker.maker.skill/140) end; q=math.min(2.5,q); BookForedgeFanMaker.productStock[m.productType]=(BookForedgeFanMaker.productStock[m.productType] or 0)+m.quantity; BookForedgeFanMaker.totalProducts=BookForedgeFanMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookForedgeFanMaker.maker then BookForedgeFanMaker.maker.itemsMade=BookForedgeFanMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookForedgeFanMaker.maker.skill=math.min(100,BookForedgeFanMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ventilator izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookforedgefan.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookForedgeFanMaker.update(dt) if not _G.state then return end; BookForedgeFanMaker.dayTimer=BookForedgeFanMaker.dayTimer+dt; if BookForedgeFanMaker.dayTimer>=30 then BookForedgeFanMaker.dayTimer=0; for i=#BookForedgeFanMaker.activeMaking,1,-1 do local m=BookForedgeFanMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookForedgeFanMaker.completeMaking(m); table.remove(BookForedgeFanMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookForedgeFanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookForedgeFanMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
